            new ColumnDoc("best_pep", "Lowest `pep` among the supporting PSMs. RUN-RELATIVE, like `Psm.pep`: rank or threshold within the dataset, never compare values across datasets or releases (definition pep:DEF-PEP).", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("target_decoy", "Target, decoy or contaminant. Decoy peptidoforms are kept so a caller can recompute FDR.", "TargetDecoy", Enum: "TargetDecoy", Identifier: false, Multivalued: false, Unit: null),
