            new ColumnDoc("protein_group_id", "Protein group the peptidoform was assigned to.", "ProteinGroup", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_accessions", "The accessions MetaMorpheus's PARSIMONY assigned the peptide to, NOT every protein whose sequence contains it. A peptide shared by a canonical and an isoform lists only the isoform when the dataset also holds a peptide unique to that isoform (aging 075, REQ-DATAREPO-5).", "Protein", Enum: null, Identifier: false, Multivalued: true, Unit: null),
            new ColumnDoc("is_unique", "PARSIMONY-unique: `protein_accessions` holds exactly one accession. It is computed from the parsimony list, not from the searched sequences, so it is `true` for a peptide that occurs in several proteins whenever parsimony assigned it to one of them (aging 075: a fibronectin peptide in P02751 and three of its isoforms reads `true`). For sequence-level specificity, check the searched database (G76). (R11, mzLib REQ-MZLIB-1)", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
