            new ColumnDoc("engine_full_sequences", "The producer's own notation for this peptidoform, VERBATIM (MetaMorpheus `Full Sequence`, engine modification names such as `[Common Biological:Phosphorylation on T]`). A set, not a pick: when two engine names resolve to one UNIMOD accession, one `peptidoform` comes from two producer strings, and both are listed. `peptidoform` is the UNIMOD-resolved ProForma key; this is the engine-name form, and it is the only place a modification with no UNIMOD accession keeps its name rather than a mass tag (ptmQtl 002, DATAREPO-P3). Not ProForma: engine names are not a ProForma controlled vocabulary.", "string", Enum: null, Identifier: false, Multivalued: true, Unit: null),
        ]),
        ["protein_groups"] = new TableDoc("ProteinGroup", "One protein group in one dataset.",
        [
            new ColumnDoc("protein_group_id", "<dataset_id>:<sorted accessions joined by ;>. The accessions are SORTED, so the first one in this id is the alphabetically first and nothing else: MetaMorpheus names no leading, razor or representative protein, and neither does this id (aging 070 57h).", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
