        ["proteins"] = new TableDoc("Protein", "One UniProt entry (isoforms are separate rows).",
        [
            new ColumnDoc("protein_accession", "UniProt accession (isoform suffix kept) or custom-database ID.", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
            new ColumnDoc("canonical_accession", "Self for canonical entries.", "Protein", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene", "Primary gene name.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("organism", "NCBITaxon term of the database this entry came FROM -- the searched proteome's organism. NULL for a contaminant-database entry and for a decoy, because neither is evidence of the sample's organism: a contaminant panel is bovine, porcine, equine and bacterial by design, and a reversed decoy sequence is no organism's protein at all. It was `required: true` until schema 0.0.7, and that is exactly what made it wrong -- a required column with no true value gets a false one, so all 339 contaminant entries in aging's catalog read NCBITaxon:9606 including porcine trypsin, bovine albumin and E. coli lacZ, and `is albumin detected?` returned bovine P02769 as human ALB. Where the producer names a species, `organism_name` carries it verbatim; mapping that name to a taxon is nobody's job here yet (G36).", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("organism_name", "The producing search engine's own species name for this entry, verbatim: `Bos taurus`, `Sus scrofa`, `Equus caballus`, `Escherichia coli (strain K12)`. MetaMorpheus supplies it per accession and it is the only species evidence there is for a contaminant-panel entry. Stored as the producer wrote it and never parsed into a taxon here, because a name-to-NCBITaxon map is a reference resource this project does not own (D1); a caller that needs the CURIE joins one in.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("length", "Sequence length in residues.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("source_db", "uniprot, or the custom database that supplied it (e.g. progerin, D8).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("uniprot_release", "UniProt release the entry was taken from.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("is_contaminant", "True if the entry comes from the contaminant database.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["ptm_sites"] = new TableDoc("PtmSite", "One modified residue on one protein in one dataset, from PSM evidence.",
        [
            new ColumnDoc("ptm_site_id", "<dataset_id>:<accession>:<residue><position>:<modification_name>, with '@<site_type>' appended ONLY when site_type is not 'residue' -- so no id written before schema 0.0.5 moves (aging 024 section 4). A terminal site is keyed on the position of the residue it sits on, never on a sentinel position: a protein N-terminal acetylation and an N6-acetyllysine on residue 1 are different chemistries at the same coordinate, and a key that cannot separate them will eventually merge them. The last component is the SEARCH ENGINE'S OWN NAME for the modification (MetaMorpheus's IdWithMotif, e.g. 'Carbamidomethyl on C'), never the UNIMOD accession. Keying on UNIMOD cost sites: a modification with no UNIMOD cross-reference cannot form such a key at all, so its sites were not written as nulls -- they were not written, and a query for them returned an empty answer indistinguishable from 'never identified' (aging 019 section 3; Hydroxybutyrylation on K, 43 PSMs and 10 peptidoforms in PXD027318, 0 sites). It is not a rare shape: mzLib 1.0.591 carries a Unimod cross-reference on 86.8% of Mods.txt and 33.6% of ptmlist.txt, so a GPTMD run over UniProt annotations meets unmapped names routinely. The name is always present, which is the whole argument, and QuantProject has ruled that the native identity of a site is (database version, accession, position, IdWithMotif) with Unimod a DERIVED VIEW over it -- a derived view cannot be the key, because it cannot represent everything the engine finds. The id is also then invariant under a mapping improvement: when mzLib later gives Hydroxybutyrylation an accession, `modification` fills in and no id moves. Nothing is lost cross-dataset, because dataset_id is the first component and so this key never joins across datasets anyway: that is what the `modification` and `modification_name` COLUMNS are for. The residue is load-bearing and must not be dropped to 'simplify' the key: one UNIMOD accession covers several chemistries on different residues (UNIMOD:7 is deamidation on N and on Q and citrullination on R; UNIMOD:35 is hydroxylation on K/N/P and oxidation on M), so a key without it merges them.", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
            new ColumnDoc("dataset_id", "Dataset this row belongs to (ProteomeXchange accession).", "Dataset", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_accession", "UniProt (or custom-database) accession, isoform suffix kept.", "Protein", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("position", "Residue position in the protein (1-based).", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("residue", "Modified amino acid (one-letter code) -- for a terminal site, the residue the modification actually sits ON, not the string 'N-term'. A terminus is a position, and the thing modified there is still a residue; `site_type` carries the fact that it is terminal. Nullable because a producer can place a modification at a terminus without naming the residue, and a null is then honest where a guess would not be.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("site_type", "Where on the molecule the modification sits. Defaults to `residue`, which is what almost every row is; the terminal values exist because the ingester skipped every modification at a peptide terminus before schema 0.0.5, so `ptm_sites` held 0 rows for placements `peptidoforms` held in full. Measured on the corpus after the fix (aging 028): **2,091 terminal sites at q<=0.01** -- 1,220 `protein_n_term` and 871 `peptide_n_term`, 20,789 PSMs, `ptm_sites` 35,615 -> 38,045 with every other table identical row-for-row. (aging's pre-fix estimate of 1,367 was RETRACTED in their 029: it counted peptidoforms whose ProForma begins with a modification, which conflates the two site types and misses every first-residue placement not written as a prefix.) N-terminal acetylation is co-translational, among the most abundant marks in any proteome, and governs the N-degron pathway and so protein turnover: it is not a tail chemistry in an aging repository. A reader querying `ptm_sites` for acetylation before this got a lysine-only answer with nothing saying so.", "SiteType", Enum: "SiteType", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("modification", "UNIMOD accession, ABSENT when the search engine's modification has no UNIMOD cross-reference. A null here means 'this chemistry has no Unimod term in the registry that searched it', never 'unmodified' and never 'unknown chemistry': `modification_name` always says what it is. A caller aggregating by UNIMOD must decide what to do with these rows rather than have them silently dropped, which is what keying on UNIMOD used to do for them.", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("modification_name", "The search engine's own name for the modification, verbatim (MetaMorpheus's IdWithMotif, e.g. 'Hydroxybutyrylation on K'). Always present, and the component of ptm_site_id that makes the key always formable. It is engine-specific by construction, which is safe here because a dataset is searched by one engine and dataset_id is part of the key; cross-dataset work goes through `modification`, or through this column when both datasets share an engine.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("target_decoy", "Target or contaminant, from the supporting PSMs. Contaminant sites are kept because they are real measurements of real molecules and are used as a process control, but they are not the sample, so a caller filters on this rather than having the decision made for them.", "TargetDecoy", Enum: "TargetDecoy", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("best_ambiguity_level", "Lowest producer ambiguity level among the PSMs that placed this site (1 < 2A < 2B < 2C < 2D < 3 < 4 < 5). Sites are emitted at any level, because the producer's occupancy population applies no level filter. `best_ambiguity_level = '1' AND target_decoy = 'target'` selects exactly the site set a level-1, target-only derivation produces -- but n_psms and best_q_value on those rows count all the evidence, so they are not the same numbers that derivation would report.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("localization_score", "Producer's modification-localization score. Null for an ordinary GPTMD hit, which MetaMorpheus does not localize -- absence here means the producer computed none, not that the site is unlocalized, and a caller asking whether a site is confidently localized should be refused rather than given an empty cell.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_psms", "Accepted PSMs that placed this site, at any ambiguity level and including contaminant PSMs. This is evidence depth for the site, and it is the measure the producer's occupancy denominator is built from, so it deliberately counts more broadly than a level-1 target-only view would.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("best_q_value", "Lowest q-value among the supporting PSMs.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["ptm_stoichiometry"] = new TableDoc("PtmStoichiometry", "PTM site occupancy -- the modified fraction of one site -- in one run or sample group, as MetaMorpheus computes and writes it (the `CountOccupancy_<label>` and `IntensityOccupancy_<label>` cells of the protein-group table, read with pyMzLib `read_occupancy`). Never computed here (D29): the ingester stores both bases MetaMorpheus writes, with everything behind each fraction, because this is one of the repository's central measurements. Definitions are QuantProject's (`DEF-OCC-*`, register v3-v3.5). One row per (site, run) where a MODIFIED form was seen; a site seen only unmodified has no row, and absence is NA, never 0 (DEF-OCC-ABSENT). The two bases are authoritative in OPPOSITE halves of the cell: for counts the integers are exact and the written fraction is rounded to 2 decimals; for intensity the written fraction (4 decimals) is exact and the pair is rounded to 4 significant figures (DEF-OCC-CELL v3.2). Occupancy is MS/MS-only (MBR transfers do not enter, DEF-OCC-INT) and excludes `Common Variable` and `Common Fixed` modification types, so a default search reports no oxidation or carbamidomethyl occupancy (DEF-OCC-PSMS). No minimum evidence is applied; QuantProject recommends reading only `n_covering_psms >= 5` (DEF-OCC-MINIMUM). Which group member a site belongs to is resolved against the searched sequence, never by the `|` segment's position (DEF-OCC-ACCESSION). Not stored for TMT or SILAC datasets.",
        [
            new ColumnDoc("ptm_site_id", "The site, keyed as `ptm_sites` keys it (the engine's own modification name). MetaMorpheus's position is converted to ours: equal for a residue, 0 -> 1 with `@protein_n_term`, Length + 1 -> Length with `@protein_c_term` (DEF-OCC-KEY).", "PtmSite", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("assay_id", "The run's (or sample group's) assay. With `denominator_grouping = run` it is that raw file's label-free assay.", "Assay", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("denominator_grouping", "Whether the denominators on this row cover one run or a pooled sample group (DEF-OCC-GROUPING). Never compare the two.", "OccupancyGrouping", Enum: "OccupancyGrouping", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("sample_label", "MetaMorpheus's own `<label>` from the column name, verbatim (e.g. `..._01-calib`), so a row round-trips to the file.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_group_id", "The protein group whose cell the entry was written in.", "ProteinGroup", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("mm_position", "The position as MetaMorpheus wrote it (`pos{p}`): 1-based in the accession's sequence, 0 for the protein N-terminus, Length + 1 for the C-terminus.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("mm_modification", "The modification exactly as the cell names it (`IdWithMotif`).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("occupancy_state", "quantified, floor, count_only or intensity_unassigned (DEF-OCC-COUNTONLY). Read it before any intensity column.", "OccupancyState", Enum: "OccupancyState", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("modified_fraction_count", "Count-based occupancy AS WRITTEN (2 decimals, rounded; DEF-OCC-COUNT). For the exact value use `n_modified_psms / n_covering_psms`, which are authoritative for this basis. Kept in its own column, never merged with the intensity estimate: the two disagree threefold overall.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_modified_psms", "PSMs whose resolved form carries the modification here: the count numerator, EXACT (DEF-OCC-COUNT). Spectra, not peptides.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_covering_psms", "PSMs covering the position, modified or not: the count denominator, EXACT. An ambiguous PSM counts here for every position its base sequence covers (DEF-OCC-PSMS). This is the evidence depth; QuantProject recommends >= 5 (DEF-OCC-MINIMUM).", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("count_is_ceiling", "True when every covering PSM carried the modification (`n_modified_psms = n_covering_psms`): an occupancy of 1 means no unmodified PSM was seen, which on a shallow site is weak evidence of full occupancy. NULL with no count entry.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("modified_fraction_intensity", "Intensity-based occupancy AS WRITTEN (4 decimals), and for this basis the written fraction IS authoritative (DEF-OCC-INT, DEF-OCC-CELL v3.2). NULL when count_only.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("intensity_modified", "The intensity numerator: summed apex intensity share of the modified forms (DEF-OCC-INT), ROUNDED to 4 significant figures by the writer. NULL when count_only.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("intensity_total", "The intensity denominator: summed intensity share of every covering form, rounded to 4 significant figures. Use it to weight or pool runs: sum numerators over summed denominators, never average fractions (DEF-OCC-SYNONYM's rule). NULL when count_only.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("intensity_is_floor", "True for `occupancy_state = floor`: a fraction of 0 whose numerator is a literal 0, meaning the modified form was identified but never quantified. CENSORED, not a measured zero (DEF-OCC-INT-ZERO). NULL when count_only.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("intensity_is_ceiling", "True when the intensity fraction is 1: no unmodified covering form was quantified, the mirror of the floor. NULL when count_only.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("definition_id", "`QuantProject:DEF-OCC-CELL`, the definition of both cells and of the states; the count and intensity columns cite DEF-OCC-COUNT and DEF-OCC-INT, which it carries.", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["glycopeptides"] = new TableDoc("Glycopeptide", "One glycopeptide identification (R16). Glycans are stored as COMPOSITIONS, never structures (trap J9). Quant goes in QuantValue with feature_type glycopeptide.",
        [
