            new ColumnDoc("localization_level", "How confidently the glycan is placed on its residue.", "GlycoLocalizationLevel", Enum: "GlycoLocalizationLevel", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("q_value", "False discovery rate q-value (0-1).", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
