        ["proteoform_inferences"] = new TableDoc("ProteoformInference", "A proteoform INFERRED from bottom-up evidence (R7b; no top-down data). Sites on different peptides are not evidence of one molecule (trap J16): `sites_on_one_peptide` says whether any single peptide carries them all.",
        [
            new ColumnDoc("proteoform_id", "Stable ID of the inferred proteoform.", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
            new ColumnDoc("dataset_id", "Dataset this row belongs to (ProteomeXchange accession).", "Dataset", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_accession", "UniProt (or custom-database) accession, isoform suffix kept.", "Protein", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("proforma", "Full-protein ProForma of the inferred form.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("supporting_peptidoforms", "Peptidoforms the inference rests on.", "Peptidoform", Enum: null, Identifier: false, Multivalued: true, Unit: null),
            new ColumnDoc("sites_on_one_peptide", "True only if a single peptidoform carries every site (trap J16).", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("inference_confidence", "Producer's confidence in the inference (0-1).", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("definition_id", "Owner's definition ID giving this number its meaning.", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["quant_values"] = new TableDoc("QuantValue", "One quantity of one feature in one assay. Long format (D5). Missing = no row or NA, never 0. A stored 0 is a MEASURED zero, and occurs only where the value's definition says 0 is a measurement: a spectral count (QuantProject:DEF-PROT-SPC, no qualifying PSM). An intensity of 0 means not measured and is never stored. So count detections with `value > 0`, never by counting rows (0.18.0).",
        [
            new ColumnDoc("assay_id", "Assay (run x channel) this value was measured in.", "Assay", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("feature_type", "Which table feature_id points into.", "FeatureType", Enum: "FeatureType", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("feature_id", "ID in the table named by feature_type.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("value", "The quantity, IN THE UNITS OF ITS `definition_id` AND IN NO OTHER. This column holds several incommensurable quantities at once -- on aging's catalog, FlashLFQ intensities (median 1.2e6) and spectral counts (median 3) sit in the same column, separable only by `definition_id`. Always group or filter by `definition_id`; a median, sum or ratio taken across the bare column mixes units and is meaningless. An agent that did exactly that reported a spurious million-fold protein difference between two of aging's datasets, which is the grain rule (U8) broken inside a single column rather than between tables. Absent row or NA when not measured, never 0. A stored 0 is a measured zero and appears only for a definition that says so -- a spectral count (QuantProject:DEF-PROT-SPC); an intensity is never stored as 0. Count detections with `value > 0`, not by counting rows.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("detection_type", "How the value was obtained: MS/MS or match-between-runs.", "DetectionType", Enum: "DetectionType", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("pip_q_value", "FlashLFQ MBR peak q (PIP Q-Value).", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("mbr_kept", "Passes the producer's MBR filter (QuantProject DEF-MBR-KEPT).", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("definition_id", "e.g. apex intensity (aging D13).", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["annotation_sources"] = new TableDoc("AnnotationSource", "A versioned annotation set from its owner (go's organelle map, UniProt, half-lives…).",
        [
            new ColumnDoc("source_id", "Stable ID of the annotation set, e.g. go-organelle-map-v3.", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
            new ColumnDoc("owner_project", "Project that owns and maintains the content.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("version", "Owner's version string.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("doi", "DOI, if one has been minted.", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["protein_localizations"] = new TableDoc("ProteinLocalization", "Protein -> GO-CC term, as supplied by `go`. Never computed here. One row per (accession, term) for the accessions that carry the term themselves -- go expands its (group, term) row over `accession_used`, never over every group member (go D22) -- so a member that does not carry a term gets no row. The organelle CATEGORY is not on this row: it is a property of the term, not the protein, and lives once in `organelle_term_categories`, joined on (compartment, go_release) (go 004, DATAREPO-29/30). The row carries NO category map: under go D28 an annotation is map-independent and one annotation file serves every consumer map, so the join yields one category row per map and a query names the map it means (schema 0.0.9, go 009 section 4: `organelle_map_version` was `required` here with no true value). There is no leading-protein column and never will be: MetaMorpheus computes none, and member order is alphabetical (go D25). Contract: go's own rulings (D1-D26), not the superseded REQ-GO-2..10.",
        [
            new ColumnDoc("protein_accession", "UniProt (or custom-database) accession, isoform suffix kept.", "Protein", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("compartment", "GO-CC term the protein's own entry carries, directly or by propagation (go's `go_id`). Named `compartment` as in `organelle_age_summaries`, and because published queries join on it.", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("go_release", "GO ontology release, from the file header (go D9). With `compartment`, the key into organelle_term_categories: an ancestor edge moving between releases moves a term's category with the map unchanged (go 004 section 3).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("evidence", "Evidence code or note from the source.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("source_id", "Annotation source (owner + version) this row comes from.", "AnnotationSource", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_group", "go's `protein_group`: the MetaMorpheus group this accession was annotated in, its accessions `|`-joined in the producer's (alphabetical, not ranked) order. An accession sits in one group or the file is refused. Filled by go's released output (schema 0.0.10).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("q_value", "The GROUP's protein q-value, as go copies it from the search (go D29). The same on every row of one group. Every non-decoy group is written, so filter on it: go's header counters count at `q_value <= counter_q_value_max`.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_members", "Accessions in the group (go D22).", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_with", "Group accessions whose own entry carries this term (go D22). `n_with < n_members` means the term is not true of the whole group.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("inherited", "go's `inherited`: the term reached this accession from another entry rather than its own (go D22). Read it before treating the row as the entry's own annotation.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("propagated", "go's `propagated`: the term was reached by ancestor propagation over is_a and part_of, not annotated directly.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["organelle_term_categories"] = new TableDoc("OrganelleTermCategory", "Which organelle category a GO-CC term falls in, under one category map (name and version) and one ontology release. One row per (term, category, subcategory): a term in two categories is two rows, and nothing is ever a list paired by position. Stored once per term instead of repeated on every protein row, so two rows cannot disagree (DATAREPO-29). go writes one category file per consumer map beside each annotation file (go D28). Coverage check, refused on failure: every `compartment` here appears in the paired annotation file with the same `go_release`, since a mismatched pair stored is a join that silently drops categories (go 009 section 4; replaces the per-row cross-check, which lapsed with D28). The map's CONTENT is the consumer's (aging's `aging-organelle-map`, charter S17); go owns only the format. Producer: go.",
        [
            new ColumnDoc("compartment", "GO-CC term (go's `go_id`).", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("category_map_name", "The category map's name, from the category file header (`#!category_map <name> <version> <sha256>`), e.g. `aging-organelle-map`. With the version, it names one consumer's map: two consumers' maps can share a version number and mean different things.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("organelle_map_version", "The category map's version, from the same header line (go's `category_map_version`).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("go_release", "GO ontology release. The category is a function of the PAIR (go 004, DATAREPO-30).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("organelle_category", "go's organelle category for this term, e.g. `mitochondrion`.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("organelle_subcategory", "Qualified subcategory with its prefix kept, e.g. `mitochondrion:inner_membrane`. NULL when the category has none.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("source_id", "Annotation source (owner + version) this row comes from.", "AnnotationSource", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["gene_resolutions"] = new TableDoc("GeneResolution", "Protein -> stable Ensembl gene, as logs' resolver (mzLib `EnsemblGeneResolver`, pyMzLib `proteins.resolve_genes`) writes it for one searched database against one pinned gene set. Never computed here: the instance operator runs the released engine through `datarepo run logs.resolve_genes`, which stores its rows unchanged as an engine artefact beside the bundles (D28), never inside one. One row per (protein, gene), or one outcome row for a protein with no gene on the assembly; never a pick among several genes and never a `|`-joined cell. Columns after `definition_id` are mzLib's `GeneResolutionTsv` names. Join to `proteins` on `accession` (entry level, LOGS-D2) AND on `search_database_sha256` being a database the dataset searched: the same accession resolved from a different database or gene set is a different row. The contaminant database is not resolved, so a contaminant protein has no row, and never falls back to a target's (logs 002 section 0). A gene only Ensembl's xref links adds a row with `source = ensembl_xref` and never changes `outcome`. Producer: logs (the method, `logs:DEF-GENE-RESOLUTION v1`); the rows' inputs are the operator's.",
        [
            new ColumnDoc("definition_id", "`logs:DEF-GENE-RESOLUTION v1`. A run without Ensembl's xref is not v1 and is refused by the runner (logs 017 section 3).", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("accession", "As the search database has it, variant suffix and all.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("entry_accession", "The UniProt entry or unversioned RefSeq accession; verbatim otherwise. Joins to `proteins.protein_accession` (the same accession under the name logs' artefact uses); the catalog's `protein_genes` view has already made that join.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("isoform", "UniProt isoform number. NULL: the accession has no `-N` suffix.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("namespace", "`uniprot`, `refseq` or `unrecognized`.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("outcome", "What the resolver found for this protein. The same on every row of one protein.", "GeneResolutionOutcome", Enum: "GeneResolutionOutcome", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_genes", "Genes on the gene set's assembly linked to this protein. 0 is a count, not a missing value.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene_id", "Stable Ensembl gene id (`ENSG...`). NULL: no gene on the assembly (the outcome says why).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("versioned_gene_id", "The gene id as the database wrote it. NULL: no gene.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene_symbol", "The gene set release's symbol, for display only. NULL: no gene, or the release names none.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene_biotype", "The gene set release's biotype. NULL: no gene.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("off_primary_genes", "Linked genes OUTSIDE the gene set (ALT haplotypes, patches), not counted in `n_genes`. 0 is a count.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("uniprot_gene_name", "The database entry's own primary gene name, a label. NULL: the entry gives none.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("source", "`search_database_dbreference`, or `ensembl_xref` for a gene only Ensembl links.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("search_database_sha256", "sha256 of the decompressed searched database. Equal to the sha256 a bundle's `bundle.json` records for that database.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene_set_release", "Ensembl release of the gene set, e.g. `116`. NULL: the GTF's name carried none.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("gene_set_sha256", "sha256 of the Ensembl GTF the gene set was made from. The runner checks it against logs' manifest.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("ensembl_xref_agrees", "Whether Ensembl's UniProt xref links this pair. NULL: the row has no gene (unknown, not false).", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("ensembl_xref_info_type", "Ensembl's evidence for the link (`DIRECT`, `SEQUENCE_MATCH`, `INFERRED_PAIR`). NULL: no xref link.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("ensembl_xref_sha256", "sha256 of Ensembl's UniProt xref file. Always present: v1 requires the xref.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
        ]),
        ["protein_annotations"] = new TableDoc("ProteinAnnotation", "Any other per-protein fact from an owner (R6: half-life with tissue/organism, ELLP, genome of origin, complex membership; R5 orthologs). Key/value so new facts need no schema change.",
