        ["findings"] = new TableDoc("Finding", "A flag on a dataset or run (low_id_rate, no_design_file, a SUSPICIOUS.md entry…).",
        [
            new ColumnDoc("finding_id", "Stable ID of the finding.", "string", Enum: null, Identifier: true, Multivalued: false, Unit: null),
            new ColumnDoc("dataset_id", "Dataset this row belongs to (ProteomeXchange accession).", "Dataset", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("run_id", "Run the finding is about, if it is run-specific.", "Run", Enum: null, Identifier: false, Multivalued: false, Unit: null),
