        ]),
        ["trait_effects"] = new TableDoc("TraitEffect", "How one feature changes with one consumer-defined trait, in one scope. Generic: the trait is a `trait_id` the consuming project defines (for aging, `aging:DEF-AGE-EFFECT ...`), and this table knows nothing about any trait. Producer: ptmQtl, through mzLib (ptmQtl D1-D10). For v1 the model is a two-part hurdle per peptidoform, fitted over runs where its protein group is quantified: a detection part and an intensity part, each reported, plus a combined p. A part with too little support is `estimable_* = false` with NULL estimates -- the flag, not the NULL, is the answer, so \"not estimable\" never reads as \"no effect\". aging's `age_effects` is a different table from a different producer (aging's own protein-level fits) and is unchanged. SHAPE ONLY: nothing writes this table until the mzLib engine exists.",
        [
            new ColumnDoc("feature_type", "What the feature is: `peptidoform` in v1; `glycopeptide` and `ptm_site` (ptmQtl's occupancy_site) later.", "FeatureType", Enum: "FeatureType", Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("feature_key", "Cross-dataset feature key: the peptidoform's ProForma with the engine's modification names (ptmQtl D6). Keeps modifications with no UNIMOD accession distinct.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("feature_key_unimod", "The same feature as UNIMOD-resolved ProForma, i.e. `peptidoforms.peptidoform`, which is the join into this repository. NULL only if the producer could not resolve it.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("protein_accessions", "EVERY accession of the feature's protein group, never the first: MetaMorpheus member order is alphabetical, not a choice (go D25).", "Protein", Enum: null, Identifier: false, Multivalued: true, Unit: null),
            new ColumnDoc("trait_id", "Consumer-defined trait with version, e.g. `aging:DEF-AGE-EFFECT v1.2`.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("response", "What was regressed: `pf_beyond_protein` (peptidoform intensity with protein-group intensity as covariate), `modified_fraction`, `abundance`.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("scope", "A dataset accession for a within-dataset fit, or `meta` for the cross-dataset one.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("beta_detect", "Trait coefficient of the detection (logistic) part. NULL exactly when estimable_detect is false.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("se_detect", "Standard error of beta_detect.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("p_detect", "p-value of beta_detect.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("beta_int", "Trait coefficient of the intensity part, over runs where the feature was detected. NULL exactly when estimable_int is false.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("se_int", "Standard error of beta_int.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("p_int", "p-value of beta_int.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("p_combined", "Combined p over the estimable parts.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("q", "Multiple-testing q-value within fdr_family.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("fdr_family", "The family q was computed within, e.g. `pf_beyond_protein.biological`. Families are split by modification class so artefact sites do not spend the biological budget.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_detected", "Runs where the feature was detected.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_absent_protein_present", "Runs where its protein group was quantified and the feature was absent -- informative for the detection part.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("n_protein_present", "Runs where its protein group was quantified; runs without it are dropped for this feature.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("estimable_detect", "Detection part had minimum support (>=3 detected, >=3 absent with protein present).", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("estimable_int", "Intensity part had minimum support.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            new ColumnDoc("mbr_dependent", "The result does not survive an MS/MS-only refit.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
