    /// <summary>Each study layer's tables' documentation, by layer.</summary>
    public static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, TableDoc>> StudyTables = new Dictionary<string, IReadOnlyDictionary<string, TableDoc>>
    {
        ["aging"] = new OrderedTables
        {
            ["sample_ages"] = new TableDoc("SampleAge", "Normalized age of one sample. NOT YET DEFINITION-BACKED (DATAREPO-5). The normalizer is SdrfAge (sdrf/mzLib #1326) and dataRepo only stores what it returns -- parsing an age string is not this repository's job (D1). Only about 160 of 1,236 curated SDRFs carry a real age (aging G12), so absence is common and is NA. No dataset in the instance populates this table today: the three ingested SDRFs carry only organism and biological replicate.",
            [
                new ColumnDoc("sample_id", "Sample this row describes.", "Sample", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_raw", "The SDRF value verbatim, so a normalizer change can be re-run against the source rather than against a previous normalization.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_years", "Normalized to years. NA when not parseable, which is not the same as no age being recorded -- `age_raw` distinguishes them.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_is_lower_bound", "True for a right-censored age such as '65+' or '>=90Y'. `aging:DEF-AGE-EFFECT v1` section 5 EXCLUDES these from a primary fit and counts them in `n_age_lower_bound`; they are never silently treated as the bound value, because the datasets most likely to carry them are the ones with the oldest donors.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_is_range", "True if the SDRF gives a range (e.g. 60-69Y).", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_source", "Where `age_raw` came from: an SDRF cell, or the study owner's curation from a named source.", "AgeSource", Enum: "AgeSource", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_source_reference", "For a curated age, the source it was read from (for example 'PMID 40544948' or 'PRIDE PXD056433 project record'). NULL for an SDRF age, whose source is the SDRF.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("normalizer_version", "Version of the software that turned `age_raw` into `age_years` (SdrfAge). Two rows normalized by different versions are not comparable and this is how a caller can tell. NULL when no normalizer ran, e.g. a curated age converted by hand; never a curation label (that is `age_source`).", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            ]),
            ["curated_sample_characteristics"] = new TableDoc("CuratedSampleCharacteristic", "One characteristic of one sample, as aging CURATED it (aging 078, REQ-DATAREPO-6). The values come from the PRIDE record, the deposit's own files and the paper, not from an SDRF cell. That is the whole reason this is a study table and not a core one. The core `samples` and `sample_characteristics` hold only what an SDRF wrote, and a curated value never enters them, so \"the depositor said\" and \"aging read it from the paper\" can never be confused. Being in this table is the mark that a value is aging's. The same rule as `sample_ages.age_source = curated`, except that here every row is curated. A NULL `samples.organism_part` / `cell_type` / `cell_line` / `disease` does not mean nothing is known about the sample. It means no SDRF term was written. Read this table before reporting a sample's tissue, cell type, cell line or disease as unknown. It is keyed per sample, so a value that holds for a whole dataset is one row per sample, and a per-run condition (control vs progeria on the same deposit) needs no extra table.",
            [
                new ColumnDoc("sample_id", "Sample this row describes. Must be a sample the catalog holds.", "Sample", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("name", "The characteristic, written the way an SDRF column header is, e.g. `characteristics[organism part]`, `characteristics[cell type]`, `characteristics[cell line]`, `characteristics[disease]`. It is the same vocabulary as `sample_characteristics.name`, so the two can be read side by side on one filter. Part of the key: one curated value per characteristic per sample.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("value", "The curated value as a name, e.g. `SH-SY5Y`, `brain`, `Hutchinson-Gilford progeria syndrome`, `normal`, or an SDRF reserved word the curator wrote: `not applicable` (the characteristic does not apply, e.g. the tissue of a cell line) or `not available` (the sources were read and do not say). No row means the characteristic was not curated at all. Those are three different answers (G42), so filter on `value_reserved` before counting values.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("value_reserved", "True when `value` is an SDRF reserved word (`not available`, `not applicable`, `unknown`, `none`, `na`, `n/a`), the same list and meaning as `sample_characteristics.value_reserved`: the curator looked and there is no value. Computed by `datarepo study` from `value`. A delivered value that disagrees is refused. A reserved row is not an annotation.", "boolean", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("term", "The ontology term for `value` where the curator gave one: UBERON (organism part), CL (cell type), Cellosaurus `CVCL_` (cell line), MONDO or DOID (disease; PATO:0000461 for normal).", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("source_reference", "What the value was read from, e.g. `PMID 40544948`, `PRIDE PXD050351 project record`, `PXD036557 samples_names.docx`. REQUIRED, as for a curated age: a curated value whose source cannot be named is not delivered.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("evidence", "The curator's note: the sentence, table cell or mapping the value rests on. Verbatim, and free text.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("confidence", "aging's own rating of the row, verbatim (`high`, `medium`, `low` in `aging-curation/1`). It is aging's vocabulary, so it is not an enum here. Filter on it before trusting a `low` row like the others.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("curation_version", "The curation that produced the row, e.g. `aging-curation/1`. Two rows from different curation versions may disagree by design, and this is how a caller can tell. It is a curation label, not software. It is never written into `sample_ages.normalizer_version`, which names software.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            ]),
            ["age_effects"] = new TableDoc("AgeEffect", "The estimated change in one measured quantity, for one feature, per DECADE of donor age, fitted WITHIN a single dataset, with its uncertainty and the evidence behind it. Content is `aging:DEF-AGE-EFFECT v1`; every column below is named by that definition. Four rules the shape enforces. PER DECADE, not per year: the datasets span 30-70 years and a per-year coefficient invites multiplication by a lifetime it was never fitted over. WITHIN ONE DATASET: raw intensities are not comparable across datasets (trap J3), so pooling happens in `age_effect_meta` over effect sizes only. AND A FIT THAT FAILED WRITES NO ROW: the reason goes to `age_effect_refusals`, because a null beta would make \"no evidence\" and \"no effect\" look the same. ONE ORGANISM, and never corrected for it (`aging:DEF-AGE-EFFECT v1.1`, aging 039/040): `beta` is per decade of chronological age within one organism. It is never expressed in lifespan fractions, life stages or human-equivalent years, and the decade is ten years for every organism -- a per-organism denominator is a lifespan correction wearing a different hat. Any cross-species comparison is a separate, named quantity computed at read time from `beta` and `age_mappings`, never a different meaning for this column.",
            [
                new ColumnDoc("dataset_id", "Dataset the fit was performed within.", "Dataset", Enum: null, Identifier: false, Multivalued: false, Unit: null),
