                new ColumnDoc("quant_basis", "Whether MBR-transferred peaks counted as present. Part of the key: both are computed and both are stored, so DEF-Q4 being open does not block the fit.", "QuantBasis", Enum: "QuantBasis", Identifier: false, Multivalued: false, Unit: null),
