                new ColumnDoc("stratum", "Which samples the fit ran over: `all`, `sex=female`, `sex=male` (D13), or `incl_censored` for the sensitivity fit that includes right-censored ages at face value (definition section 5). ASK: left as a string rather than an enum because the definition's own section 5 adds a value its section 2 table does not list, so the vocabulary is demonstrably open. DATAREPO-20 asks whether to close it.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("beta", "The coefficient on `age_decades = (age_years - age_centre_years) / 10`: change PER DECADE of chronological age, within one organism, in the units of the response's transform -- log2 fold change for abundance and isoform_ratio, logit change for the fractions. Required, because a row exists only when a fit succeeded.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("se", "Standard error of `beta`. REQUIRED: the definition's section 4 says a beta without an se is not an age effect.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
