                new ColumnDoc("ci_high", "Upper bound of the confidence interval on `beta`.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("p_value", "Unadjusted p-value for `beta`.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("q_value", "Benjamini-Hochberg q-value WITHIN (dataset_id, response, estimator, quant_basis, model_form, stratum). The family is the set of features tested together and nothing else, so a q-value here may not be compared with one from another family.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_samples", "Samples that entered the fit. At least 8, or no row was written.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_observed", "Samples with a non-missing value for this feature.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_missing", "Samples with a missing value. Missing is NA and is OMITTED from the fit, never imputed -- imputation is a modelling choice with its own definition and it is not this one.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_min", "Youngest donor age in the fit, in years.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_max", "Oldest donor age in the fit, in years.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("age_span_years", "The span the effect was fitted over. REQUIRED, and it is the column that stops a reader treating a per-decade effect from a 12-year span as evidence about a lifetime.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_age_lower_bound", "How many donor ages were right-censored. Excluded from a primary fit; see `stratum = incl_censored` for the sensitivity fit.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("covariates", "The terms ACTUALLY FITTED, semicolon-separated. REQUIRED, and read strictly: a row whose covariates do not list a term did not adjust for it, whatever the protocol said. `sex` is not optional where the dataset has two levels with at least two samples each, and a dataset with more than one condition must carry a disease/condition term or the age effect absorbs the group difference.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("normalization", "What was applied before fitting, e.g. `median_log2_per_run`. Required because `DEF-PROT-INT` is un-normalized when FlashLFQ's Normalize is off, which is what every run in the instance used, so a fit that does not say what it normalized cannot be read.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
