                new ColumnDoc("intensity_is_floor_frac", "modified_fraction + estimator=intensity only. Fraction of the observations that were DEF-OCC-INT-ZERO floors rather than measured values. A row where this is high is mostly censored data.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
