                new ColumnDoc("model_form", "The model form that was not fitted.", "ModelForm", Enum: "ModelForm", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("stratum", "The stratum that was not fitted.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
