                new ColumnDoc("definition_id", "`aging:DEF-AGE-EFFECT v1`, whose section 5 sets the thresholds this row failed.", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            ]),
            ["age_effect_meta"] = new TableDoc("AgeEffectMeta", "The pooled age effect for one feature ACROSS datasets. Content is `aging:DEF-AGE-EFFECT-META v1`; a separate table from AgeEffect because combining datasets is a different operation with different failure modes. The pooling is RANDOM-EFFECTS (DerSimonian-Laird), not fixed: these are different cohorts, tissues and instruments, and a fixed-effect model would assert one true effect. The stratification columns are refusals in disguise -- never pool across acquisition (DDA with DIA), across quant_method (label-free with TMT) or across tissue, because H6, I3 and D4 ask whether those AGREE and a pooled estimate would destroy the question -- and NEVER ACROSS ORGANISM (`aging:DEF-AGE-EFFECT-META v1.2` section 6.4, our G40), the strongest member of that family and the one first left unwritten because every dataset was human. It is a key column, not a stated invariant, because an invariant cannot be checked: today a UniProt accession is species-specific and happens to keep a human and a mouse effect apart, but an orthology-resolved feature id (`logs`) spans species by construction, and the moment one enters this table the accession stops being the guard. `n_datasets = 1` is a legitimate row carrying a null `i_squared`. It is not a meta-analysis; it is an honest statement that one dataset exists, which is the state of this repository for every tissue it holds.",
            [
                new ColumnDoc("organism", "NCBITaxon term. FIRST component of the key and a hard stratification (`aging:DEF-AGE-EFFECT-META v1.2` section 6.4): every contributing `age_effects` row carries this organism, and a pooled estimate over two organisms is not written. Pooling across species on purpose is a different, named operation that does not exist yet.", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("feature_type", "Which kind of feature this row pools. ASK (DATAREPO-20): the definition's section 6 key omits feature_type, but without it `feature_id` cannot be interpreted -- and a dataset-scoped identifier such as a protein_group_id cannot be a cross-dataset key at all, so the cross-dataset identity of a feature is itself the question.", "FeatureType", Enum: "FeatureType", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("feature_id", "Identifier of the feature, in whatever vocabulary is cross-dataset for its type. ASK (DATAREPO-20): see feature_type.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("response", "What changes with age. Part of the key.", "AgeResponse", Enum: "AgeResponse", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("estimator", "Part of the key.", "AgeEstimator", Enum: "AgeEstimator", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("quant_basis", "Part of the key.", "QuantBasis", Enum: "QuantBasis", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("stratum", "Part of the key.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("tissue", "UBERON term. Part of the key, and a hard stratification: D4 asks whether the lysosome shows the same trend in brain as in muscle, which is two rows.", "uriorcurie", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("acquisition", "Part of the key, and a hard stratification: H6 and I3 ask whether DDA and DIA agree.", "Acquisition", Enum: "Acquisition", Identifier: false, Multivalued: false, Unit: null),
