                new ColumnDoc("beta_meta", "Random-effects (DerSimonian-Laird) pooled effect, per decade, in the response's transform units.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("se_meta", "Standard error of the pooled effect. Required for the same reason `se` is on AgeEffect.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("ci_low", "Lower bound of the confidence interval on `beta_meta`.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
