                new ColumnDoc("q_meta", "Benjamini-Hochberg across features within the same stratum.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_datasets", "How many datasets contributed.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("dataset_ids", "WHICH datasets contributed. C3 and D1 ask for an effect seen in at least three datasets and need the list, not the count.", "Dataset", Enum: null, Identifier: false, Multivalued: true, Unit: null),
                new ColumnDoc("i_squared", "I-squared heterogeneity across datasets. Null when n_datasets = 1, which is not a defect.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("tau2", "Between-dataset variance. H1's forest plot is made of this and i_squared.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_direction_agree", "Contributing datasets whose effect has the same sign as the pooled one. H6 and I3 want direction agreement rather than a pooled p-value.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("n_direction_disagree", "Contributing datasets whose effect has the opposite sign.", "integer", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("leave_one_out_max_delta", "The largest change in `beta_meta` from dropping any single dataset. C2 asks whether the age effect is driven by one dataset, and this answers it as a number rather than a judgement. Null when n_datasets = 1.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("definition_id", "`aging:DEF-AGE-EFFECT-META v1.2` (v1.2 added `organism` to the key and the never-pool-across-organism rule).", "Definition", Enum: null, Identifier: false, Multivalued: false, Unit: null),
