                new ColumnDoc("cv_mae_years", "Cross-validated mean absolute error in years.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("heldout_mae_years", "Mean absolute error on held-out datasets, in years. A clock with no held-out error has not been validated, and the two columns are separate so that cannot be hidden.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("heldout_datasets", "Datasets held out for validation.", "Dataset", Enum: null, Identifier: false, Multivalued: true, Unit: null),
