                new ColumnDoc("feature_type", "Which table feature_id points into.", "FeatureType", Enum: "FeatureType", Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("feature_id", "Identifier of the feature in the table named by feature_type.", "string", Enum: null, Identifier: false, Multivalued: false, Unit: null),
                new ColumnDoc("weight", "Model weight of the feature.", "float", Enum: null, Identifier: false, Multivalued: false, Unit: null),
            ]),
            ["age_mappings"] = new TableDoc("AgeMapping", "Cross-species age to life stage (R4). NOT YET DEFINITION-BACKED and NOT STARTED: rodent is in scope (D5) and has no age mapping. aging's, confirmed in their 039 (their requirement R4 assigned it to their stage 7 before rodents were in scope): an ANALYSIS CHOICE, not a fact about a sample, which is why it is neither sdrf's to curate nor ours to derive. dataRepo stores it as a versioned, definition-backed lookup. aging have said on the record that they will not publish a single scalar conversion: a mapping carries its source and its disagreement, or it is a refusal.",
            [
