    /// <summary>Each study layer's own enums, by layer.</summary>
    public static readonly IReadOnlyDictionary<string, IReadOnlyDictionary<string, EnumDoc>> StudyEnums = new Dictionary<string, IReadOnlyDictionary<string, EnumDoc>>
    {
        ["aging"] = new OrderedEnums
        {
            ["AgeResponse"] = new EnumDoc("What changes with age. `aging:DEF-AGE-EFFECT v1` section 1: an age effect is always OF a named response, because a protein's abundance and a site's modified fraction are different age effects on the same molecule and the point of this repository is that they can disagree. Never one column.", ["abundance", "modified_fraction", "isoform_ratio", "glycoform_fraction"]),
            ["AgeSource"] = new EnumDoc("Where a sample's `age_raw` came from (aging 071, DATAREPO-59). Kept apart from `normalizer_version`, which names software: putting a curation label there would give one column two meanings, and a caller comparing normalizer versions would compare a label.", ["sdrf", "curated"]),
            ["AgeEstimator"] = new EnumDoc("Which estimator produced the response, where a response has more than one. QuantProject 017: count-based and intensity-based stoichiometry differ about threefold and MUST NEVER be averaged, so they are separate rows rather than one number.", ["count", "intensity", "n/a"]),
            ["QuantBasis"] = new EnumDoc("Whether a match-between-runs transferred peak was counted as present. `DEF-Q4` asks which is right and the user has not ruled; the definition's answer is to compute both and store both rows, so the unanswered question becomes a column the repository can be queried on (H8+).", ["msms_only", "mbr_kept"]),
            ["ModelForm"] = new EnumDoc("The shape fitted in age. H7+ asks whether the trend is linear or has a breakpoint.", ["linear", "spline", "breakpoint"]),
            ["FitRefusal"] = new EnumDoc("Why a fit was not performed. Closed list, from `aging:DEF-AGE-EFFECT v1` section 5. When a minimum-evidence requirement fails, NO row is written to `age_effect` -- not a row with a null beta -- because an absent age effect and an age effect of zero are different facts.", ["n_too_small", "age_span_too_narrow", "too_few_distinct_ages", "too_missing", "batch_confounded", "no_age_metadata"]),
        },
    };
}
